"use client";

/*
 * MeshGradient: the Neon brand-deck gradient as a live WebGL surface —
 * a defocused warm color field (moss, ember, gold, and a yellow-green
 * bloom) drifting over near-black. A brand background for heroes,
 * covers, and marketing moments. Static single frame under reduced
 * motion. GLSL lives in mesh-gradient-shader.ts.
 */

import { useEffect, useRef } from "react";
import type { ComponentProps } from "react";

import { cn } from "@/lib/utils";

import { MESH_FRAGMENT, MESH_VERTEX } from "./mesh-gradient-shader";

export type MeshGradientPalette = [
  base: string,
  moss: string,
  ember: string,
  gold: string,
  bloom: string,
];

export type MeshGradientProps = Omit<ComponentProps<"canvas">, "children"> & {
  /** Animation speed multiplier; 0 freezes the field. */
  speed?: number;
  /** 0-1 domain warp — how organic the blob edges get. */
  warp?: number;
  /** 0-1 dither strength; keeps soft falloffs from banding. */
  grain?: number;
  /** Brightness multiplier on the bloom blob. */
  glow?: number;
  /** The field, painted back to front: [base, moss, ember, gold, bloom]. */
  colors?: MeshGradientPalette;
};

const DEFAULT_COLORS: MeshGradientPalette = [
  "#0b0b08",
  "#2c4a33",
  "#a85f1b",
  "#edbf4e",
  "#eef2a0",
];

const parseColor = (css: string): [number, number, number] => {
  const probe = document.createElement("canvas");
  probe.width = 1;
  probe.height = 1;
  const context = probe.getContext("2d");

  if (!context) {
    return [0, 0, 0];
  }

  context.fillStyle = css;
  context.fillRect(0, 0, 1, 1);
  const [r, g, b] = context.getImageData(0, 0, 1, 1).data;
  return [(r ?? 0) / 255, (g ?? 0) / 255, (b ?? 0) / 255];
};

const warnDev = (message: string) => {
  if (typeof process !== "undefined" && process.env.NODE_ENV !== "production") {
    console.warn(message);
  }
};

const compile = (
  gl: WebGLRenderingContext,
  type: number,
  source: string
): WebGLShader | null => {
  const shader = gl.createShader(type);

  if (!shader) {
    return null;
  }

  gl.shaderSource(shader, source);
  gl.compileShader(shader);

  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    warnDev(
      `neon-ui: shader compile failed: ${gl.getShaderInfoLog(shader) ?? "unknown"}`
    );
    gl.deleteShader(shader);
    return null;
  }

  return shader;
};

export const MeshGradient = ({
  className,
  colors = DEFAULT_COLORS,
  glow = 1,
  grain = 0.5,
  speed = 0.6,
  warp = 0.4,
  ...props
}: MeshGradientProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [base, moss, ember, gold, bloom] = colors;

  useEffect(() => {
    const canvas = canvasRef.current;
    const gl = canvas?.getContext("webgl", { alpha: false });

    if (!(canvas && gl)) {
      return;
    }

    const vertex = compile(gl, gl.VERTEX_SHADER, MESH_VERTEX);
    const fragment = compile(gl, gl.FRAGMENT_SHADER, MESH_FRAGMENT);
    const program = gl.createProgram();

    if (!(vertex && fragment && program)) {
      if (vertex) {
        gl.deleteShader(vertex);
      }
      if (fragment) {
        gl.deleteShader(fragment);
      }
      return;
    }

    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);

    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      warnDev(
        `neon-ui: program link failed: ${gl.getProgramInfoLog(program) ?? "unknown"}`
      );
      gl.deleteProgram(program);
      gl.deleteShader(vertex);
      gl.deleteShader(fragment);
      return;
    }

    // oxlint-disable-next-line react/react-compiler -- WebGL method, not a React hook
    gl.useProgram(program);

    const quad = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, quad);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]),
      gl.STATIC_DRAW
    );
    const position = gl.getAttribLocation(program, "a_position");
    gl.enableVertexAttribArray(position);
    gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

    const uResolution = gl.getUniformLocation(program, "u_resolution");
    const uTime = gl.getUniformLocation(program, "u_time");
    const uWarp = gl.getUniformLocation(program, "u_warp");
    const uGrain = gl.getUniformLocation(program, "u_grain");
    const uGlow = gl.getUniformLocation(program, "u_glow");

    gl.uniform1f(uWarp, warp);
    gl.uniform1f(uGrain, grain);
    gl.uniform1f(uGlow, glow);

    for (const [name, css] of [
      ["u_base", base],
      ["u_moss", moss],
      ["u_ember", ember],
      ["u_gold", gold],
      ["u_bloom", bloom],
    ] as const) {
      const [r, g, b] = parseColor(css);
      gl.uniform3f(gl.getUniformLocation(program, name), r, g, b);
    }

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let frame = 0;
    let staticFrame = false;

    const renderStatic = () => {
      gl.uniform1f(uTime, 11);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    const resize = () => {
      const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.round(canvas.clientHeight * dpr));

      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
        gl.viewport(0, 0, width, height);
      }

      gl.uniform2f(uResolution, canvas.width, canvas.height);
    };

    const observer = new ResizeObserver(() => {
      resize();

      if (staticFrame) {
        renderStatic();
      }
    });
    observer.observe(canvas);
    resize();

    const dispose = () => {
      observer.disconnect();
      gl.deleteBuffer(quad);
      gl.deleteProgram(program);
      gl.deleteShader(vertex);
      gl.deleteShader(fragment);
    };

    const draw = (now: number) => {
      // Skip GL work while hidden (e.g. behind a docs Code overlay's
      // visibility:hidden panel) — keep the loop alive, drop the cost.
      if (!(canvas.checkVisibility?.() ?? true)) {
        frame = requestAnimationFrame(draw);
        return;
      }

      gl.uniform1f(uTime, (now / 1000) * speed);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      frame = requestAnimationFrame(draw);
    };

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");

    if (reduced.matches || speed === 0) {
      staticFrame = true;
      resize();
      renderStatic();
      return dispose;
    }

    frame = requestAnimationFrame(draw);

    return () => {
      cancelAnimationFrame(frame);
      dispose();
    };
  }, [base, bloom, ember, glow, gold, grain, moss, speed, warp]);

  return (
    <canvas
      aria-hidden="true"
      className={cn("size-full", className)}
      data-slot="mesh-gradient"
      ref={canvasRef}
      {...props}
    />
  );
};

/*
 * The visual shader for MeshGradient, kept separate from the React
 * mount.
 *
 * A recreation of the Neon brand-deck gradient: a defocused color
 * field on a near-black base, studied blob by blob from the slide —
 *
 * - a large bright yellow-green bloom left of center
 * - a golden lobe pinned to the top-right corner
 * - a burnt ember mass across the right middle
 * - deep moss green in the top-left corner
 * - the warm black base showing through between the blobs
 *
 * The source slide also carries a dark scrim along the bottom for its
 * copy; that is deliberately NOT part of the field — text protection
 * is the consumer's overlay, not the gradient's.
 *
 * Each region is a gaussian blob with its own slow orbit; a gentle
 * value-noise warp keeps the edges organic, and a fine dither kills
 * the banding that soft falloffs otherwise show on 8-bit displays.
 *
 * Fragment shader uniforms:
 * - u_resolution (vec2): canvas resolution in pixels
 * - u_time (float): animation time in seconds (pre-multiplied by speed)
 * - u_warp (float): 0-1 domain warp on the blob field
 * - u_grain (float): 0-1 dither strength
 * - u_glow (float): brightness multiplier on the bloom blob
 * - u_base / u_moss / u_ember / u_gold / u_bloom (vec3): the palette,
 *   painted in that order from back to front
 */

export const MESH_VERTEX = `
attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}
`;

export const MESH_FRAGMENT = `
precision mediump float;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_warp;
uniform float u_grain;
uniform float u_glow;
uniform vec3 u_base;
uniform vec3 u_moss;
uniform vec3 u_ember;
uniform vec3 u_gold;
uniform vec3 u_bloom;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = smoothstep(0.0, 1.0, fract(p));
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

/* Gaussian falloff: 1 at the center, soft shoulder, long tail. The
   stretch squashes distance per axis, elongating the blob. */
float blob(vec2 p, vec2 center, float radius, vec2 stretch) {
  vec2 d = (p - center) / stretch;
  return exp(-dot(d, d) / (radius * radius));
}

/* A slow elliptical orbit unique to each blob. */
vec2 orbit(float t, float phase, float amount) {
  return vec2(cos(t * 0.11 + phase), sin(t * 0.07 + phase * 1.7)) * amount;
}

void main() {
  float aspect = u_resolution.x / u_resolution.y;
  vec2 uv = gl_FragCoord.xy / u_resolution;
  vec2 p = vec2(uv.x * aspect, uv.y);
  float t = u_time;

  // Organic edges: push the sample point around with slow value noise.
  vec2 warp = vec2(
    vnoise(p * 1.4 + vec2(t * 0.03, 0.0)),
    vnoise(p * 1.4 + vec2(7.3, t * 0.025))
  );
  p += (warp - 0.5) * u_warp * 0.55;

  // Paint back to front, each blob mixing toward its own color; the
  // moss corner goes last so the bloom's halo never washes it out.
  vec3 color = u_base;

  float gold = blob(
    p, vec2(1.02 * aspect, 1.0) + orbit(t, 4.2, 0.04), 0.62, vec2(1.15, 1.0));
  color = mix(color, u_gold, min(gold * 1.1, 1.0));

  float bloom = blob(
    p, vec2(0.36 * aspect, 0.64) + orbit(t, 5.6, 0.06), 0.55, vec2(1.3, 1.0));
  color = mix(color, u_bloom * u_glow, min(bloom * 1.25, 1.0));

  float ember = blob(
    p, vec2(0.78 * aspect, 0.46) + orbit(t, 2.1, 0.05), 0.55, vec2(1.2, 1.0));
  color = mix(color, u_ember, min(ember * 0.9, 1.0));

  float moss = blob(
    p, vec2(0.0, 1.06) + orbit(t, 0.0, 0.03), 0.42, vec2(1.0, 1.25));
  color = mix(color, u_moss, min(moss * 0.95, 1.0));

  // Fine dither so the soft falloffs don't band on 8-bit displays.
  color += (hash(gl_FragCoord.xy) - 0.5) * (u_grain * 0.035);

  gl_FragColor = vec4(color, 1.0);
}
`;
